<?php
declare(strict_types=1); date_default_timezone_set('Europe/London');
$db=new PDO('sqlite:/var/lib/predictioncomp/player-wordle/game.sqlite3');
function statrows($db,$days){$q=$db->prepare("SELECT c.name,SUM(s.started) started,SUM(s.completed) completed,SUM(s.won) won FROM aggregate_stats s JOIN clubs c ON c.id=s.club_id WHERE s.stat_date>=date('now',?) GROUP BY c.id ORDER BY c.name");$q->execute(['-'.$days.' days']);return $q->fetchAll(PDO::FETCH_ASSOC);}
$total=(int)$db->query("SELECT COALESCE(SUM(started),0) FROM aggregate_stats")->fetchColumn();
?><!doctype html><html><head><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="style.css"><title>Player Wordle Admin</title></head><body><header><div class="brand"><b>PLAYER</b><span>WORDLE</span></div><p>Statistics</p></header><main><h1>Game statistics</h1><div class="notice"><b><?=number_format($total)?></b> recorded game starts. No user profiles, IPs, accounts or identifiers are stored.</div><?php foreach([1=>'Today',7=>'Last 7 days',30=>'Last 30 days'] as $d=>$title):?><h2><?=$title?></h2><div style="overflow:auto"><table><tr><th>Club</th><th>Started</th><th>Completed</th><th>Won</th></tr><?php foreach(statrows($db,$d) as $r):?><tr><td><?=htmlspecialchars($r['name'])?></td><td><?=$r['started']?></td><td><?=$r['completed']?></td><td><?=$r['won']?></td></tr><?php endforeach?></table></div><?php endforeach?></main><style>table{width:100%;border-collapse:collapse;background:#101f31}td,th{padding:10px;border-bottom:1px solid #263547;text-align:left}</style></body></html>